def transform(grid):
    h, w = len(grid), len(grid[0])

    # Uniform lines can include rows/columns of the background. The true
    # separator color is the least frequent color among uniform-line colors.
    line_colors = set()
    for r in range(h):
        if len(set(grid[r])) == 1:
            line_colors.add(grid[r][0])
    for c in range(w):
        vals = {grid[r][c] for r in range(h)}
        if len(vals) == 1:
            line_colors.add(next(iter(vals)))

    if not line_colors:
        return [row[:] for row in grid]
    freq = {v: sum(row.count(v) for row in grid) for v in line_colors}
    sep_color = min(line_colors, key=lambda v: freq[v])

    row_divs = [r for r in range(h) if all(v == sep_color for v in grid[r])]
    col_divs = [c for c in range(w) if all(grid[r][c] == sep_color for r in range(h))]
    rb = [-1] + row_divs + [h]
    cb = [-1] + col_divs + [w]

    top, bottom = rb[0] + 1, rb[1]
    left, right = cb[0] + 1, cb[1]
    template = [grid[r][left:right] for r in range(top, bottom)]

    counts = {}
    for row in template:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)

    out = [row[:] for row in grid]
    for i in range(len(rb) - 1):
        r0, r1 = rb[i] + 1, rb[i + 1]
        for j in range(len(cb) - 1):
            c0, c1 = cb[j] + 1, cb[j + 1]
            for dr in range(min(r1 - r0, len(template))):
                for dc in range(min(c1 - c0, len(template[0]))):
                    v = template[dr][dc]
                    if v != background:
                        out[r0 + dr][c0 + dc] = v
    return out
